create temp table replay_tenants (seq integer primary key, tenant_id uuid not null, members uuid[] not null, last_at timestamptz);
create temp table replay_steps (seq integer, step integer, kind integer, accepted boolean, matches boolean, primary key (seq, step));
create temp table replay_mismatches (seq integer, step integer, kind integer, want text, have text);
create temp table replay_runs (tenant_id uuid, at timestamptz);

create function pg_temp.replay_sequence(p_seq integer)
returns void
language plpgsql
as $$
declare
  v_doc jsonb := (select doc from replay);
  v_sequence jsonb := (select doc -> 'sequences' -> p_seq from replay);
  v_tenant uuid := gen_random_uuid();
  v_account uuid := gen_random_uuid();
  v_store uuid := gen_random_uuid();
  v_programme uuid := gen_random_uuid();
  v_members uuid[] := '{}'::uuid[];
  v_coupons uuid[] := '{}'::uuid[];
  v_earns uuid[] := '{}'::uuid[];
  v_holds uuid[] := '{}'::uuid[];
  v_clock timestamptz := (v_doc ->> 'start')::timestamptz;
  v_step jsonb;
  v_index integer := 0;
  v_kind integer;
  v_member integer;
  v_a integer;
  v_b integer;
  v_accepted boolean;
  v_id uuid;
  v_invoice uuid;
  v_result jsonb;
  v_want text;
  v_have text;
  i integer;
begin
  insert into public.tenants (id, slug, name, country_code) values (v_tenant, 'ledger-replay-' || p_seq, 'Ledger replay ' || p_seq, 'VN');
  insert into public.pos_accounts (id, tenant_id, connector, account_key, display_name) values (v_account, v_tenant, 'mock', 'ledger-replay-' || p_seq, 'Synthetic account');
  insert into public.stores (id, tenant_id, pos_account_id, external_id, name) values (v_store, v_tenant, v_account, 'lr-' || p_seq, 'Synthetic store');
  insert into public.loyalty_programmes (id, tenant_id, name, starts_on, notification_decision, status, welcome_stamps, earning_invoices_per_phone_per_day, stamp_validity_months, points_expiry_months)
  values (v_programme, v_tenant, 'Synthetic programme', date '2026-01-01', 'below_threshold', 'active', 0, 20,
    (v_doc -> 'rules' ->> 'stampValidityMonths')::smallint, (v_doc -> 'rules' ->> 'pointsExpiryMonths')::smallint);
  insert into public.coupon_rails (tenant_id, store_id, rail, crm_programme_external_ids, active_from)
  values (v_tenant, v_store, 'pos_payment_discount', '{}'::text[], timestamptz '2026-01-01 00:00+07');
  for i in 0 .. jsonb_array_length(v_doc -> 'coupons') - 1 loop
    insert into public.coupon_rail_rewards (tenant_id, store_id, reward_key, pos_discount_name, crm_programme_external_id, einvoice_display)
    values (v_tenant, v_store, 'lr-' || i, 'Synthetic entry ' || i, null, 'discount');
    insert into public.coupons (tenant_id, programme_id, reward_key, name, reward_kind, cost_stamps, cost_points, status)
    values (v_tenant, v_programme, 'lr-' || i, 'Synthetic reward ' || i, 'free_item',
      (v_doc -> 'coupons' -> i ->> 0)::smallint, (v_doc -> 'coupons' -> i ->> 1)::integer, 'active')
    returning id into v_id;
    v_coupons := v_coupons || v_id;
  end loop;
  for i in 0 .. 2 loop
    v_members := v_members || app.loyalty_join(v_tenant, app.loyalty_customer_for_phone(v_tenant, '090024400' || i), 'mini_app', v_store, null, null, v_clock - interval '1 day');
  end loop;

  for v_step in select s.value from jsonb_array_elements(v_sequence -> 'steps') s loop
    v_clock := v_clock + make_interval(mins => (v_step ->> 0)::integer);
    v_kind := (v_step ->> 1)::integer;
    v_member := (v_step ->> 2)::integer;
    v_a := (v_step ->> 3)::integer;
    v_b := (v_step ->> 4)::integer;
    v_accepted := false;
    case v_kind
      when 0 then
        insert into public.invoices (tenant_id, store_id, pos_account_id, external_id, receipt_no, sold_at, business_date, gross_amount, net_amount, paid_amount)
        values (v_tenant, v_store, v_account, 'lr-' || p_seq || '-' || v_index, '1', v_clock - interval '5 minutes',
          app.store_business_date(v_store, v_clock - interval '5 minutes'), v_a * 1000, v_a * 1000, v_a * 1000)
        returning id into v_invoice;
        select e.entry_id into v_id from app.loyalty_earn(v_invoice, v_members[v_member + 1], 'A', v_clock, v_b = 1) e;
        if v_id is not null then
          v_earns := v_earns || v_id;
          v_accepted := true;
        end if;
      when 1 then
        begin
          perform app.loyalty_confirm(v_earns[v_a + 1], null, v_clock);
          v_accepted := true;
        exception when sqlstate '22023' then
          v_accepted := false;
        end;
      when 2 then
        v_result := app.redeem_coupon(v_members[v_member + 1], v_coupons[v_a + 1], v_store, v_clock);
        if v_result ->> 'state' = 'held' then
          v_holds := v_holds || (v_result ->> 'redemption_id')::uuid;
          v_accepted := true;
        end if;
      when 3 then
        -- a voided invoice confirms the hold without earning on path D (the model's confirm of a hold)
        insert into public.invoices (tenant_id, store_id, pos_account_id, external_id, receipt_no, sold_at, business_date, gross_amount, net_amount, paid_amount, status)
        values (v_tenant, v_store, v_account, 'lr-' || p_seq || '-' || v_index, '1', v_clock, app.store_business_date(v_store, v_clock), 1000, 1000, 1000, 'voided')
        returning id into v_invoice;
        v_accepted := app.confirm_redemption(v_holds[v_a + 1], v_invoice, v_clock) is not null;
      when 4 then
        v_accepted := app.release_redemption(v_holds[v_a + 1], 'hold_expired', v_clock) is not null;
      when 5 then
        v_accepted := app.loyalty_clawback((select l.invoice_id from public.loyalty_ledger l where l.id = v_earns[v_a + 1]), 'invoice_voided', v_clock) = 1;
      when 6 then
        perform app.loyalty_expire(v_tenant, v_clock);
        insert into replay_runs values (v_tenant, v_clock);
        v_accepted := true;
      when 7 then
        begin
          perform app.loyalty_apply_adjustment(v_members[v_member + 1], v_store, v_a, v_b, 'synthetic correction', null, v_clock);
          v_accepted := true;
        exception when sqlstate '22023' then
          v_accepted := false;
        end;
    end case;
    select string_agg(t.e, ',' order by t.o) into v_want from jsonb_array_elements_text(v_step) with ordinality as t (e, o) where t.o > 5;
    select (case when v_accepted then '1' else '0' end) || ',' || string_agg(concat_ws(',', b.stamps, b.points, b.pending_stamps, b.pending_points), ',' order by m.o)
    into v_have
    from unnest(v_members) with ordinality as m (id, o)
    cross join lateral app.loyalty_balance(m.id, v_clock) b;
    insert into replay_steps values (p_seq, v_index, v_kind, v_accepted, v_want = v_have);
    if v_want is distinct from v_have then
      insert into replay_mismatches values (p_seq, v_index, v_kind, v_want, v_have);
    end if;
    v_index := v_index + 1;
  end loop;

  select string_agg(t.e, ',' order by t.o) into v_want from jsonb_array_elements_text(v_sequence -> 'rows') with ordinality as t (e, o);
  select string_agg(concat_ws(',', b.stamps, b.points), ',' order by m.o) into v_have
  from unnest(v_members) with ordinality as m (id, o) cross join lateral app.loyalty_balance(m.id, null) b;
  if v_want is distinct from v_have then
    insert into replay_mismatches values (p_seq, -1, null, 'rows ' || v_want, 'rows ' || v_have);
  end if;
  select string_agg(t.e, ',' order by t.o) into v_want from jsonb_array_elements_text(v_sequence -> 'counts') with ordinality as t (e, o);
  select string_agg((select count(*) from public.loyalty_ledger l where l.tenant_id = v_tenant and l.entry_kind = k.kind)::text, ',' order by k.o) into v_have
  from unnest(array['earn', 'confirm', 'clawback', 'redeem', 'adjust', 'expire']::public.loyalty_entry_kind[]) with ordinality as k (kind, o);
  if v_want is distinct from v_have then
    insert into replay_mismatches values (p_seq, -2, null, 'counts ' || v_want, 'counts ' || v_have);
  end if;
  insert into replay_tenants values (p_seq, v_tenant, v_members, v_clock);
end;
$$;

select pg_temp.replay_sequence(s) from generate_series(0, (select jsonb_array_length(doc -> 'sequences') - 1 from replay)) s;

select is(
  (select count(*)::int from replay_tenants),
  200,
  'the 200 generated sequences ran, each in its own tenant'
);
select is(
  (select count(*)::int from replay_steps),
  (select sum(jsonb_array_length(s -> 'steps'))::int from replay, jsonb_array_elements(doc -> 'sequences') s),
  'every step of the fixture ran through the SQL functions'
);
select is(
  (select string_agg(format('sequence %s step %s (kind %s): model %s, database %s', seq, step, kind, want, have), '; ')
   from (select * from replay_mismatches where step >= 0 order by seq, step limit 5) m),
  null,
  'after every step the outcome and the four balances of the three members at that moment equal the model''s'
);
select is(
  (select string_agg(format('sequence %s: model %s, database %s', seq, want, have), '; ')
   from (select * from replay_mismatches where step < 0 order by seq, step limit 5) m),
  null,
  'at the end of every sequence the ledger rows'' balances and the rows per kind equal the model''s'
);
select is(
  (select count(distinct (kind, accepted))::int from replay_steps),
  15,
  'equivalence partitions: every kind of step ran accepted and refused (an expiry run is never refused)'
);
select ok(
  (select count(*) from public.loyalty_ledger l join replay_tenants t on t.tenant_id = l.tenant_id where l.entry_kind = 'clawback' and l.reason like '%; short by %') > 10,
  'ADR-046: clawbacks that took back what was left and wrote off the rest ran'
);
select ok(
  (select count(*) from public.loyalty_ledger e join replay_tenants t on t.tenant_id = e.tenant_id
   where e.entry_kind = 'expire'
     and not exists (select 1 from replay_runs r where r.tenant_id = e.tenant_id and r.at = e.occurred_at)) > 5,
  'ADR-047: holds and debits in the midnight-to-run window ran, each writing the ended credits'' row first'
);
select ok(
  (select count(*) from public.loyalty_ledger e join replay_runs r on r.tenant_id = e.tenant_id
   where e.entry_kind = 'earn' and e.pending and e.expires_at <= r.at and e.occurred_at <= r.at
     and not exists (select 1 from public.loyalty_ledger c where c.source_entry_id = e.id and c.entry_kind in ('confirm', 'clawback') and c.occurred_at <= r.at)) > 5,
  'ADR-046: pending earns outlived expiry runs past their sale''s expiry'
);
select is(
  (select count(*)::int from replay_tenants t cross join lateral unnest(t.members) m (id) cross join lateral app.loyalty_balance(m.id, t.last_at) b
   where b.stamps < 0 or b.points < 0 or b.pending_stamps < 0 or b.pending_points < 0),
  0,
  'no member of any sequence ends below zero'
);
select is(
  (select count(*)::int from public.loyalty_ledger l join replay_tenants t on t.tenant_id = l.tenant_id
   where l.reason ~ '(\+?84|0)[1-9][0-9]{8,9}'
      or (l.entry_kind = 'clawback' and l.reason !~ '^invoice_voided(; short by [0-9]+ (stamp|stamps|point|points)( and [0-9]+ (point|points))?)?$')),
  0,
  'security: every reason written is a reason and counts, no phone'
);

select * from finish();
rollback;
